'use strict';

// SAM v2 strict-profile specification of src/host.impl.ts: the inventory
// actor, the order actors, and the network between them. One step is one host
// command (place / cancel / restock) or the delivery of one message in transit.
//
// State:
//   available, reserved — the inventory
//   orders  — { [id]: { status, qty } } for every order placed
//   net     — the messages in transit, a sorted multiset of encoded strings:
//               'Reserve|<order>|<qty>'    order -> inventory
//               'Reserved|<order>'         inventory -> order
//               'OutOfStock|<order>'       inventory -> order
//               'Release|<order>|<qty>'    order -> inventory

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CAPACITY = 3;
const IDS = ['a', 'b', 'c'];

const INITIAL_STATE = { available: 1, reserved: 0, orders: {}, net: [] };

const add = (net, msg) => [...net, msg].sort();
const remove = (net, msg) => {
  const i = net.indexOf(msg);
  return [...net.slice(0, i), ...net.slice(i + 1)];
};

const MESSAGES = IDS.flatMap((o) => [
  `Reserve|${o}|1`, `Reserve|${o}|2`,
  `Reserved|${o}`, `OutOfStock|${o}`,
  `Release|${o}|1`, `Release|${o}|2`,
]);

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      available: { type: 'number' },
      reserved: { type: 'number' },
      orders: { type: 'object' },
      net: { type: 'array' },
    },
    actions: {
      PLACE: {
        action: (data = {}) => ({ ...data }),
        schema: { order: { type: 'string' }, qty: { type: 'number' } },
        domain: IDS.flatMap((order) => [0, 1, 2, 3].map((qty) => ({ order, qty }))),
      },
      CANCEL: {
        action: (data = {}) => ({ ...data }),
        schema: { order: { type: 'string' } },
        domain: [...IDS, 'z'].map((order) => ({ order })),
      },
      RESTOCK: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: { type: 'string' } },
        domain: MESSAGES.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      PLACE: (model) => ({ order, qty }, { reject, next, unchanged }) => {
        if (qty !== 1 && qty !== 2) return reject('bad-qty');
        if (model.orders[order]) return reject('order-exists');
        next.orders = { ...model.orders, [order]: { status: 'pending', qty } };
        next.net = add(model.net, `Reserve|${order}|${qty}`);
        unchanged('available', 'reserved');
      },
      CANCEL: (model) => ({ order }, { reject, next, unchanged }) => {
        const o = model.orders[order];
        if (!o) return reject('no-such-order');
        if (o.status === 'confirmed') {
          next.orders = { ...model.orders, [order]: { ...o, status: 'cancelled' } };
          next.net = add(model.net, `Release|${order}|${o.qty}`);
          unchanged('available', 'reserved');
          return;
        }
        if (o.status === 'pending') {
          next.orders = { ...model.orders, [order]: { ...o, status: 'cancelling' } };
          unchanged('available', 'reserved', 'net');
          return;
        }
        return reject('not-cancellable');
      },
      RESTOCK: (model) => (_p, { reject, next, unchanged }) => {
        if (model.available + model.reserved >= CAPACITY) return reject('inventory-full');
        next.available = model.available + 1;
        unchanged('reserved', 'orders', 'net');
      },
      DELIVER: (model) => ({ msg }, { reject, next, unchanged }) => {
        if (!model.net.includes(msg)) return reject('not-in-transit');
        const [action, order, q] = msg.split('|');
        const qty = Number(q);
        const net = remove(model.net, msg);
        if (action === 'Reserve') {
          if (model.available >= qty) {
            next.available = model.available - qty;
            next.reserved = model.reserved + qty;
            next.net = add(net, `Reserved|${order}`);
          } else {
            next.net = add(net, `OutOfStock|${order}`);
            unchanged('available', 'reserved');
          }
          unchanged('orders');
          return;
        }
        if (action === 'Release') {
          next.available = model.available + qty;
          next.reserved = model.reserved - qty;
          next.net = net;
          unchanged('orders');
          return;
        }
        // Reserved / OutOfStock, delivered to the order
        const o = model.orders[order];
        const isReserved = action === 'Reserved';
        if (o && o.status === 'pending') {
          next.orders = { ...model.orders, [order]: { ...o, status: isReserved ? 'confirmed' : 'rejected' } };
          next.net = net;
        } else if (o && o.status === 'cancelling') {
          next.orders = { ...model.orders, [order]: { ...o, status: 'cancelled' } };
          next.net = isReserved ? add(net, `Release|${order}|${o.qty}`) : net;
        } else {
          // delivered but ignored by the order: the message is consumed
          next.net = net;
          unchanged('orders');
        }
        unchanged('available', 'reserved');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };

const init = () => { setState(INITIAL_STATE); };

const actions = {
  PLACE: (data = {}) => intents.PLACE(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  RESTOCK: (data = {}) => intents.RESTOCK(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

