// Rules the brief requires of the orders-and-inventory system.

const CAPACITY = 3;
const TERMINAL = new Set(['rejected', 'cancelled', 'expired']);

const orders = (s) => Object.entries(s.orders);
const inTransit = (s, kind) => s.net.filter((m) => m.split('|')[0] === kind).map((m) => m.split('|'));
const qtyOf = (s, id) => s.orders[id]?.qty ?? 0;
const confirmedUnits = (s) => orders(s).filter(([, o]) => o.status === 'confirmed').reduce((n, [, o]) => n + o.qty, 0);

export const stateInvariants = [
  {
    name: 'stock-within-bounds',
    pred: (s) => s.available >= 0 && s.reserved >= 0 && s.available + s.reserved <= CAPACITY,
  },
  {
    name: 'orders-have-valid-qty',
    pred: (s) => orders(s).every(([, o]) => o.qty === 1 || o.qty === 2),
  },
  {
    // The brief's conclusion: once nothing is in transit, the reserved units are
    // exactly those of the confirmed orders.
    name: 'quiescent-reserved-equals-confirmed',
    pred: (s) => s.net.length > 0 || s.reserved === confirmedUnits(s),
  },
  {
    // Units are never lost or invented, at every instant: each reserved unit
    // belongs to a confirmed order, to a Reserved answer on its way, or to a
    // Release on its way back.
    name: 'units-accounted-for',
    pred: (s) =>
      s.reserved ===
      confirmedUnits(s) +
        inTransit(s, 'Reserved').reduce((n, [, id]) => n + qtyOf(s, id), 0) +
        inTransit(s, 'Release').reduce((n, [, , q]) => n + Number(q), 0),
  },
  {
    // A confirmed order has had its units reserved, and is not still waiting for any.
    name: 'confirmed-only-with-units-reserved',
    pred: (s) =>
      orders(s).every(([id, o]) =>
        o.status !== 'confirmed' ||
        !s.net.some((m) => m.startsWith(`Reserve|${id}|`) || m === `Reserved|${id}` || m === `OutOfStock|${id}`)),
  },
  {
    // A cancelled order has nothing reserved: no Reserved answer is still owed to it
    // without the Release to follow.
    name: 'cancelled-holds-nothing',
    pred: (s) => orders(s).every(([id, o]) => o.status !== 'cancelled' || !s.net.includes(`Reserved|${id}`)),
  },
  {
    // Only a confirmed order can expire, so an expired order went through
    // confirmation: nothing is still owed to it or awaited by it.
    name: 'expired-only-from-confirmed',
    pred: (s) =>
      orders(s).every(([id, o]) =>
        o.status !== 'expired' ||
        !s.net.some((m) => m.startsWith(`Reserve|${id}|`) || m === `Reserved|${id}` || m === `OutOfStock|${id}`)),
  },
];

export const transitionInvariants = [
  {
    name: 'terminal-orders-stay-terminal',
    pred: (pre, _a, _d, post) =>
      Object.entries(pre.orders).every(([id, o]) => !TERMINAL.has(o.status) || post.orders[id]?.status === o.status),
  },
  {
    name: 'orders-never-disappear-or-change-qty',
    pred: (pre, _a, _d, post) =>
      Object.entries(pre.orders).every(([id, o]) => post.orders[id] && post.orders[id].qty === o.qty),
  },
  {
    name: 'expire-only-confirmed',
    pred: (pre, _a, _d, post) =>
      Object.entries(post.orders).every(([id, o]) =>
        o.status !== 'expired' || pre.orders[id]?.status === 'expired' || pre.orders[id]?.status === 'confirmed'),
  },
  {
    name: 'restock-adds-exactly-one',
    pred: (pre, a, _d, post) =>
      a !== 'RESTOCK' || pre === post || JSON.stringify(pre) === JSON.stringify(post) ||
      (post.available === pre.available + 1 && post.reserved === pre.reserved),
  },
];

export default { stateInvariants, transitionInvariants };

// Negative control: seed known bugs into copies of the spec and confirm the
// invariants catch every one. Run: node spec/controls/negative.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { check, loadSpec } from '../../tools/polygraph/scripts/check.mjs';
import * as invariants from '../invariants.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const source = readFileSync(join(here, '..', 'orders.spec.cjs'), 'utf8');
const contract = JSON.parse(readFileSync(join(here, '..', 'contract.json'), 'utf8'));

const MUTANTS = {
  'cancelling-forgets-release': ['next.net = isReserved ? add(net, `Release|${order}|${o.qty}`) : net;', 'next.net = net;'],
  'cancel-confirmed-no-release': ['next.net = add(model.net, `Release|${order}|${o.qty}`);', 'next.net = model.net;'],
  'expire-no-release': ["next.orders = { ...model.orders, [order]: { ...o, status: 'expired' } };\n        next.net = add(model.net, `Release|${order}|${o.qty}`);", "next.orders = { ...model.orders, [order]: { ...o, status: 'expired' } };\n        next.net = model.net;"],
  'expire-from-pending': ["if (o.status !== 'confirmed') return reject('not-confirmed');", "if (o.status !== 'confirmed' && o.status !== 'pending') return reject('not-confirmed');"],
  'restock-ignores-reserved': ['if (model.available + model.reserved >= CAPACITY)', 'if (model.available >= CAPACITY)'],
  'reserve-without-check': ['if (model.available >= qty) {', 'if (true) {'],
  'confirm-on-out-of-stock': ["status: isReserved ? 'confirmed' : 'rejected'", "status: 'confirmed'"],
};

mkdirSync(join(here, 'out'), { recursive: true });
let failures = 0;
for (const [name, [from, to]] of Object.entries(MUTANTS)) {
  if (!source.includes(from)) throw new Error(`mutant ${name}: pattern not found`);
  const file = join(here, 'out', `${name}.cjs`);
  writeFileSync(file, source.replace(from, to));
  const r = check({ specModule: loadSpec(file), contract, invariants });
  const caught = r.violations.map((v) => v.name ?? v.invariant).filter(Boolean);
  console.log(`${caught.length ? 'caught ' : 'MISSED '} ${name}: ${[...new Set(caught)].join(', ')}`);
  if (!caught.length) failures++;
}
process.exit(failures ? 1 : 0);

