// Drives the implementation and the polygraph spec in lockstep over random
// runs, and checks after every step that they agree on the observable state.
import { test } from 'node:test';
import assert from 'node:assert/strict';
// @ts-ignore -- untyped polygraph helper
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';

const spec = loadSpec(new URL('../spec/orders.spec.cjs', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const IDS = ['a', 'b', 'c'];

const encode = (m: Message): string =>
  m.action === 'Reserve' ? `Reserve|${m.from}|${m.data.qty}`
  : m.action === 'Release' ? `Release|${m.from}|${m.data.qty}`
  : `${m.action}|${m.to}`;

async function observe(h: Host) {
  const orders: Record<string, unknown> = {};
  for (const id of IDS) {
    const o = await h.order(id);
    if (o) orders[id] = o;
  }
  const net = (await h.inFlight()).map(encode).sort();
  return { ...(await h.stock()), orders, net };
}

const canon = (s: any) => ({ available: s.available, reserved: s.reserved, open: s.open, orders: s.orders, net: [...s.net].sort() });

test('implementation conforms to the spec over random runs', async () => {
  let seed = 12345;
  const rand = (n: number) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
  for (let run = 0; run < 300; run++) {
    const h = await createHost();
    spec.init();
    for (let step = 0; step < 25; step++) {
      const pre = await observe(h);
      const kind = rand(8);
      let refused = false;
      if (kind === 0) {
        const data = { order: IDS[rand(3)], qty: rand(4) };
        refused = !(await h.place(data.order, data.qty)).ok;
        spec.actions.PLACE(data);
      } else if (kind === 1) {
        const data = { order: [...IDS, 'z'][rand(4)] };
        refused = !(await h.cancel(data.order)).ok;
        spec.actions.CANCEL(data);
      } else if (kind === 2) {
        refused = !(await h.restock()).ok;
        spec.actions.RESTOCK({});
      } else if (kind === 3) {
        const data = { order: [...IDS, 'z'][rand(4)] };
        refused = !(await h.expire(data.order)).ok;
        spec.actions.EXPIRE(data);
      } else if (kind === 4) {
        refused = !(await h.close()).ok;
        spec.actions.CLOSE({});
      } else if (kind === 5) {
        refused = !(await h.open()).ok;
        spec.actions.OPEN({});
      } else {
        const msgs = await h.inFlight();
        if (!msgs.length) continue;
        const m = msgs[rand(msgs.length)];
        await h.deliver(m.id);
        spec.actions.DELIVER({ msg: encode(m) });
      }
      const post = await observe(h);
      if (refused) assert.deepEqual(post, pre, 'a refused command changed state');
      assert.deepEqual(canon(spec.getState()), canon(post), `run ${run} step ${step}`);
    }
  }
});

