import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('place, reserve, confirm', async () => {
  const h = await createHost();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.deepEqual(await h.place('a', 1), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 1 } });
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
  const [ans] = await h.inFlight();
  assert.equal(ans.action, 'Reserved');
  assert.equal(ans.to, 'a');
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
});

test('refusals', async () => {
  const h = await createHost();
  assert.equal((await h.place('a', 3)).ok, false);
  assert.equal((await h.place('a', 0)).ok, false);
  assert.equal(await h.order('a'), null);
  await h.place('a', 1);
  assert.equal((await h.place('a', 2)).ok, false);
  assert.equal((await h.cancel('zz')).ok, false);
  assert.equal((await h.restock()).ok, true);
  assert.equal((await h.restock()).ok, true);
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 3, reserved: 0, open: true });
});

test('out of stock rejects', async () => {
  const h = await createHost();
  await h.place('a', 2);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'rejected', qty: 2 });
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('cancel confirmed releases', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.deliverAll();
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.order('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.cancel('a')).ok, false);
});

test('cancel pending, then reserved answer releases', async () => {
  const h = await createHost();
  await h.place('a', 1);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.order('a'))!.status, 'cancelling');
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('cancel pending, out of stock answer', async () => {
  const h = await createHost();
  await h.place('a', 2);
  await h.cancel('a');
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});

test('expire a confirmed order releases its units', async () => {
  const h = await createHost();
  await h.place('a', 1);
  assert.equal((await h.expire('a')).ok, false); // pending
  await h.deliverAll();
  assert.deepEqual(await h.expire('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.expire('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.place('a', 1)).ok, false);
  assert.equal((await h.expire('zz')).ok, false);
});

test('expire refused for rejected, cancelling, cancelled', async () => {
  const h = await createHost();
  await h.place('r', 2);
  await h.deliverAll();
  assert.equal((await h.expire('r')).ok, false);
  await h.place('c', 1);
  await h.cancel('c');
  assert.equal((await h.expire('c')).ok, false);
  await h.deliverAll();
  assert.equal((await h.expire('c')).ok, false);
  assert.equal((await h.order('c'))!.status, 'cancelled');
});

test('close and open', async () => {
  const h = await createHost();
  assert.equal((await h.open()).ok, false);
  assert.deepEqual(await h.close(), { ok: true });
  assert.equal((await h.close()).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  assert.deepEqual(await h.open(), { ok: true });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.restock()).ok, true);
});

test('closed inventory answers OutOfStock and still takes Release', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.deliverAll();
  await h.close();
  await h.place('b', 1);
  await h.cancel('a');
  await h.deliverAll();
  assert.equal((await h.order('b'))!.status, 'rejected');
  assert.equal((await h.order('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
});

test('a Reserve sent while open but delivered while closed is refused', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.close();
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'rejected');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
});

test('restock refused counts reserved', async () => {
  const h = await createHost();
  await h.restock();
  await h.place('a', 2);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2, open: true });
  assert.equal((await h.restock()).ok, true);
  assert.equal((await h.restock()).ok, false);
});

